// ── Page title bar — rendered inside each scrolling page ─────────────────────
export function PageHeader() {
  const { pathname } = useLocation();
  const { manualRefresh, refreshing } = useLiveData();
  const meta = PAGE_META[pathname] ?? PAGE_META['/'];
  return (
    <div className="mb-0">
      <div className="flex items-start justify-between mb-3">
        <div>
          <h1 className="text-lg font-black text-white leading-tight">{meta.title}</h1>
          <p className="text-xs mt-0.5" style={{ color: '#64748b' }}>{meta.sub}</p>
        </div>
        <button
          onClick={manualRefresh}
          disabled={refreshing}
          className={`btn btn-ghost text-xs flex items-center gap-1.5 flex-shrink-0 ml-4 ${refreshing ? 'opacity-60' : ''}`}>
          <span className={refreshing ? 'animate-spin inline-block' : ''}>🔄</span>
          {refreshing ? 'Sync…' : 'Actualiser'}
        </button>
      </div>
      <FilterBar />
    </div>
  );
}

function ProtectedRoute({ path, element }: { path: string; element: React.ReactNode }) {
  const { canAccess } = useAuth();
  if (!canAccess(path)) return <Navigate to="/welcome" replace />;
  return <>{element}</>;
}

function AppShell() {
  const { user } = useAuth();
  const { sgdCount } = useLiveData();
  if (!user) return <Login />;
  return (
    <>
    <div className="flex h-screen overflow-hidden">
      <ParticleBackground />
      <Sidebar />
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header />
        <main className="flex-1 overflow-y-auto p-6" style={{ background:"#020817" }}>
          <Routes>
            <Route path="/welcome"   element={<Welcome />} />
            <Route path="/"          element={<ProtectedRoute path="/"          element={<Dashboard   key={sgdCount} />} />} />
            <Route path="/importers" element={<ProtectedRoute path="/importers" element={<Importers   key={sgdCount} />} />} />
            <Route path="/fraud"     element={<ProtectedRoute path="/fraud"     element={<Fraud       key={sgdCount} />} />} />
            <Route path="/delays"    element={<ProtectedRoute path="/delays"    element={<Delays      key={sgdCount} />} />} />
            <Route path="/offices"   element={<ProtectedRoute path="/offices"   element={<Offices     key={sgdCount} />} />} />
            <Route path="/ai"        element={<Navigate to="/advanced" replace />} />
            <Route path="/graph"     element={<ProtectedRoute path="/graph"     element={<GraphPage   key={sgdCount} />} />} />
            <Route path="/predictions"element={<ProtectedRoute path="/predictions"element={<Predictions key={sgdCount} />} />} />
            <Route path="/analytics"  element={<Navigate to="/advanced" replace />} />
            <Route path="/officers"   element={<ProtectedRoute path="/officers"   element={<OfficersPage key={sgdCount} />} />} />
            <Route path="/advanced"   element={<ProtectedRoute path="/advanced"   element={<AdvancedPage key={sgdCount} />} />} />
            <Route path="*"          element={<Navigate to="/welcome" replace />} />
          </Routes>
        </main>
      </div>
    </div>
    <AIChat />
    </>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <LiveDataProvider>
        <FilterProvider>
        <BrowserRouter>
          <AppShell />
        </BrowserRouter>
        </FilterProvider>
      </LiveDataProvider>
    </AuthProvider>
  );
}
